# IMPERIA COLD WAR — January 1970 approval concept; no runtime writes.
"""Canonical policy, effects and coordinate model. All numbers are balance proposals."""

PREFIX = "COLDWAR_CUB_"
NODES, GROUPS = [], []

LABELS = {
    "production_speed_buildings_factor": "Construction speed",
    "civilian_factories_productivity": "Civilian industry productivity",
    "industrial_capacity_factory": "Military factory output",
    "agricolture_productivity_modifier": "Agricultural productivity",
    "agriculture_district_income_tax_modifier": "Agricultural district tax income",
    "production_factory_efficiency_gain_factor": "Production efficiency growth",
    "production_factory_max_efficiency_factor": "Production efficiency cap",
    "tax_gain_multiplier_modifier": "Tax revenue multiplier",
    "international_market_income_modifier": "Equipment market sales income",
    "resource_export_multiplier_modifier": "Resource export revenue",
    "total_workforce_modifier": "Available workforce",
    "research_speed_factor": "Research speed",
    "political_power_factor": "Political power gain",
    "stability_factor": "Stability",
    "drift_defence_factor": "Ideology drift defence",
    "foreign_influence_defense_modifier": "Foreign influence defence",
    "foreign_influence_modifier": "Foreign influence",
    "bureaucracy_cost_multiplier_modifier": "Weekly bureaucracy expenditure",
    "health_cost_multiplier_modifier": "Weekly healthcare expenditure",
    "education_cost_multiplier_modifier": "Weekly education expenditure",
    "social_cost_multiplier_modifier": "Weekly welfare expenditure",
    "army_personnel_cost_multiplier_modifier": "Weekly army personnel expenditure",
    "healthcare_workforce_requirement_modifier": "Healthcare workforce requirement",
    "healthcare_income_multiplier_modifier": "Healthcare sector income",
    "monthly_population": "Monthly population growth factor",
    "migration_rate_value_factor": "Native migration rate",
    "imp_refugee_integration_rate": "Refugee integration rate",
    "imp_sanction_resistance": "Imperia sanction resistance",
    "intelligence_agency_defense": "Counterintelligence defence",
    "army_org_factor": "Division organisation",
    "army_core_defence_factor": "Core territory defence",
    "army_attack_factor": "Division attack",
    "army_defence_factor": "Division defence",
    "training_time_army_factor": "Division training time",
    "supply_consumption_factor": "Supply consumption",
    "army_fuel_consumption_factor": "Army fuel consumption",
    "special_forces_cap": "Special forces capacity",
    "send_volunteer_size": "Volunteer division limit",
}
BAD_HIGH = {k for k in LABELS if "cost_multiplier" in k} | {"training_time_army_factor", "supply_consumption_factor", "army_fuel_consumption_factor", "healthcare_workforce_requirement_modifier"}


def group(key, title, root, slot=None, summary="", status="Historical policy / alternate institutional choices"):
    GROUPS.append(dict(id=key, label=title, root=root, slot=slot, summary=summary, historical_status=status))


def fx(kind, **kwargs):
    return dict(kind=kind, **kwargs)


def money(value): return fx("treasury", amount=value)
def building(state, typ, province=None): return fx("building", state=state, building=typ, level=1, province=province)
def tech(category, bonus=.25, uses=1): return fx("research", category=category, bonus=bonus, uses=uses)
def doctrine(bonus=.25, uses=1): return fx("doctrine", category="land_doctrine", bonus=bonus, uses=uses)
def xp(army=0, navy=0, air=0): return fx("experience", army=army, navy=navy, air=air)
def law(kind): return fx("law", helper=kind)
def offer(key): return fx("offer", contract=key)


def focus(key, title, group_id, x, y, description, modifiers=None, effects=None,
          parents=(), cost=5, icon=None, extra_gate="", history="Historically grounded policy; numerical effects are balance proposals"):
    g = next(g for g in GROUPS if g["id"] == group_id)
    NODES.append(dict(id=PREFIX+key, key=key, title=title, group=group_id, xy=[g["root"][0]+x,g["root"][1]+y],
                      local_xy=[x,y], anchor=None, cost=cost, days=cost*7, description=description,
                      modifiers=modifiers or {}, effects=effects or [], prerequisites=[[PREFIX+p for p in row] if isinstance(row,(tuple,list)) else [PREFIX+row] for row in parents],
                      mutually_exclusive=[], slot=g["slot"], extra_gate=extra_gate,
                      icon=icon or {"economy":"sugartobaccocuba","society":"cubabattleofidea","defence":"CUB_far_cub","foreign":"tradeagreementcuba"}.get(group_id,"newcubanconstitutioncuba"),
                      historical_status=history, lifetime="Party programme; inactive outside its exact governing subparty" if g["slot"] is not None else "Persistent national reform; one-time assets remain national",
                      reference="MD Cuba local policy fork; Russia institutional programme / native dynamic-modifier reward idiom"))


def exclusive(a,b):
    by={n["key"]:n for n in NODES}
    by[a]["mutually_exclusive"].append(PREFIX+b); by[b]["mutually_exclusive"].append(PREFIX+a)


# Shared country programmes: deliberate section gaps, no party-unlock meta-focus.
group("economy","The Harvest and the Economy",[8,0],summary="Mobilisation, sugar versus food, infrastructure and ownership priorities.")
focus("harvest_accounts","Harvest Accounts","economy",0,0,"The target of ten million tons has drawn workers, lorries and fuel away from the rest of the economy. JUCEPLAN needs reliable accounts before ministers can distinguish a genuine production gain from a transfer of shortages.",{"civilian_factories_productivity":.04,"bureaucracy_cost_multiplier_modifier":.03},[money(-.15)],cost=3)
focus("finish_zafra","Finish the Zafra","economy",-2,1,"The leadership can still concentrate the nation on the cane fields. Finishing the campaign preserves revolutionary authority and raises farm output, but workshops and housing must wait for their workers to return.",{"agricolture_productivity_modifier":.12,"total_workforce_modifier":.02,"production_speed_buildings_factor":-.04},[fx("harvest_course",course="mobilisation")],parents=["harvest_accounts"])
focus("restore_sectors","Restore the Sectors","economy",2,1,"Transport depots, repairs and consumer production cannot remain subordinate to a single target. Returning labour to those sectors offers a broader recovery, at the political cost of admitting that willpower has limits.",{"production_speed_buildings_factor":.10,"civilian_factories_productivity":.08,"agricolture_productivity_modifier":-.04},[fx("harvest_course",course="rebalance"),fx("stability",amount=-.03)],parents=["harvest_accounts"])
focus("rail_lorries","Rail and Lorries","economy",0,2,"Cane left beside a broken railway earns no foreign exchange. A coordinated programme for rail sidings, lorry repairs and port approaches will serve the entire economy after the harvest has ended.",effects=[money(-.60),building(854,"infrastructure"),tech("CAT_infrastructure")],parents=[("finish_zafra","restore_sectors")],cost=7,icon="transporttr")
focus("sugar_exports","Sugar for Export","economy",-4,3,"Reliable sugar exports can purchase machinery and fuel that Cuba cannot yet produce. This programme protects the cash-crop economy, accepting greater exposure to foreign buyers instead of promising that specialization is free.",{"agricolture_productivity_modifier":.15,"agriculture_district_income_tax_modifier":.08,"imp_sanction_resistance":-.05},parents=["rail_lorries"])
focus("food_first","Food before Sugar","economy",0,3,"Vegetables, dairy herds and domestic staples compete with sugar for land and skilled labour. Greater food security offers resilience under pressure, while reducing the export receipts available for imported equipment.",{"agricolture_productivity_modifier":.10,"imp_sanction_resistance":.12,"agriculture_district_income_tax_modifier":-.10},parents=["rail_lorries"])
focus("mill_mechanisation","Mill Mechanisation","economy",-4,4,"Investment must reach the mills and their agricultural hinterland together. Mechanisation can make an export priority productive without relying on another nationwide diversion of unpaid labour.",effects=[money(-.70),building(854,"agriculture_district")],parents=["sugar_exports"],cost=7)
focus("anap_cooperatives","ANAP Cooperatives","economy",0,4,"ANAP's small farmers need purchasing arrangements and a credible return for their work. Cooperative development will strengthen local food production while leaving a larger share of its proceeds with producers.",{"total_workforce_modifier":.02,"agriculture_district_income_tax_modifier":-.06},[money(-.70),building(1121,"agriculture_district")],parents=["food_first"],cost=7)
focus("moa_refinery","Moa's Refinery","economy",4,3,"The nickel industry around Moa gives eastern Cuba an industrial role beyond sugar. Refining and maintenance capacity should be expanded before another prestige project competes for imported machinery and trained technicians.",effects=[money(-.90),building(855,"industrial_complex")],parents=["rail_lorries"],cost=7,icon="CUB_mining")
focus("repair_grid","Repair the Grid","economy",4,4,"Industrial expansion requires dependable electricity. Restoring generation in central Cuba will reduce interruptions, but the new plant will consume fuel through the existing national energy system.",effects=[money(-.65),building(1121,"fossil_powerplant")],parents=["moa_refinery"],cost=7,icon="infra_habanna")
focus("light_industry","Light Industry","economy",4,5,"Textiles, food processing and household goods deserve an industrial programme of their own. A civilian factory in central Cuba will support a more diversified economy rather than another promise of immediate abundance.",{"civilian_factories_productivity":.06},[money(-.90),building(1121,"industrial_complex")],parents=["repair_grid"],cost=7,icon="cuban_economy_peso_new")
focus("protected_enterprises","Protected Enterprises","economy",2,6,"State enterprises can retain their domestic market while being held to production and maintenance targets. Protection reduces external exposure, but it also leaves investment dependent on domestic resources and administrative discipline.",{"civilian_factories_productivity":.12,"imp_sanction_resistance":.10,"production_speed_buildings_factor":-.05},[fx("enterprise_reform",model="protected")],parents=["light_industry"])
focus("joint_ventures","Joint Ventures","economy",6,6,"Foreign partners can supply equipment and market access under negotiated Cuban ownership rules. Their participation accelerates investment, while profit concessions and outside leverage limit the state's freedom of action.",{"production_speed_buildings_factor":.12,"civilian_factories_productivity":.06,"production_factory_efficiency_gain_factor":.08,"tax_gain_multiplier_modifier":-.04,"foreign_influence_defense_modifier":-.10},[fx("enterprise_reform",model="mixed")],parents=["light_industry"],history="Alternate early opening; no claim that the post-1993 investment model already existed in 1970")
focus("havana_ports","Havana's Ports","economy",-8,3,"Cuba's foreign trade depends on a small number of harbours and their approaches. Improvements around Havana will support commercial traffic and coastal supply without granting the island a new battle fleet.",effects=[money(-.55),building(854,"naval_base",7622)],parents=["rail_lorries"],cost=7,icon="tradeagreementcuba")
focus("oil_reserve","Oil Shock Reserve","economy",-8,4,"A disruption in imported oil would reach farms, electricity and transport together. Storage is a practical insurance policy; it creates reserve capacity rather than fuel that has never been purchased.",effects=[money(-.35),building(854,"fuel_silo")],parents=["havana_ports"],icon="infra_habanna")
exclusive("finish_zafra","restore_sectors");exclusive("sugar_exports","food_first");exclusive("protected_enterprises","joint_ventures")

group("society","The Social State",[20,0],summary="Preserve achievements while choosing how to fund and distribute scarce skilled labour.")
focus("social_promise","The Social Promise","society",0,0,"Literacy and public medicine are among the revolution's strongest claims to legitimacy. Maintaining those achievements requires an honest commitment of teachers, doctors and national income, even when consumer supplies remain scarce.",{"research_speed_factor":.03,"education_cost_multiplier_modifier":.05},[law("increase_education_budget")],cost=5)
focus("rural_clinics","Rural Clinics","society",-2,1,"Rural families need regular access to trained medical staff, not simply a distant hospital on paper. Local clinics use scarce personnel efficiently, but their staffing and supplies remain a recurring public expense.",{"healthcare_workforce_requirement_modifier":-.08,"monthly_population":.03,"health_cost_multiplier_modifier":.08},[money(-.45)],parents=["social_promise"])
focus("teaching_hospitals","Teaching Hospitals","society",2,1,"Concentrating equipment and specialist training in major hospitals can develop a stronger medical profession. It improves research and sector output, while requiring more expensive facilities than a dispersed basic service.",{"research_speed_factor":.06,"healthcare_income_multiplier_modifier":.08,"health_cost_multiplier_modifier":.12},[money(-.55)],parents=["social_promise"])
focus("health_workforce","Health Workforce","society",0,2,"The health service needs a sustainable establishment of doctors, nurses and technical staff. Its next budget settlement should fund actual provision through the existing spending system, rather than disguise expenditure as a free national bonus.",effects=[law("increase_healthcare_budget"),money(-.15)],parents=[("rural_clinics","teaching_hospitals")])
# COLDWAR_CUB — IMPERIA CW: medical missions incur healthcare expenditure, no workforce reduction.
focus("medical_brigades","Medical Brigades","society",-2,3,"Cuban doctors can build durable relationships where military assistance cannot. A partner must request the mission and share its terms. Overseas accommodation, medical supplies and replacement coverage require a larger public healthcare budget.",{"foreign_influence_modifier":.12,"health_cost_multiplier_modifier":.10},[offer("medical_mission")],parents=["health_workforce"])
focus("retain_doctors","Retain the Doctors","society",2,3,"Keeping newly trained medical staff at home will strengthen ordinary public provision. The policy forgoes some international influence in return for a service that reaches more Cuban households.",{"healthcare_income_multiplier_modifier":.12,"total_workforce_modifier":.02,"foreign_influence_modifier":-.04},parents=["health_workforce"])
focus("science_schools","Schools of Science","society",0,4,"Universities and technical schools must produce the engineers and laboratory staff required by a modern economy. Their graduates will improve research and available skills, while the expanded education budget continues to be paid each week.",{"total_workforce_modifier":.03,"education_cost_multiplier_modifier":.06},[money(-.30),tech("CAT_electronics",.25,2)],parents=[("medical_brigades","retain_doctors")],cost=7)
exclusive("rural_clinics","teaching_hospitals");exclusive("medical_brigades","retain_doctors")

group("defence","The Revolutionary Armed Forces",[30,0],summary="A credible defence, or a costly expeditionary establishment; no free starting army.")
focus("far_reorganisation","Reorganise the FAR","defence",0,0,"The guerrilla victory of 1959 is not a substitute for a professional staff, dependable logistics and modern training. The FAR must prepare for the threats Cuba actually faces rather than measure prestige by the size of its equipment requests.",effects=[money(-.25),xp(army=25),doctrine()],cost=5)
focus("territorial_defence","Territorial Defence","defence",-2,1,"Dispersed positions, trained reserves and knowledge of the island favour a defensive war. This doctrine makes Cuba harder to invade while accepting less emphasis on offensive operations beyond its shores.",{"army_core_defence_factor":.10,"army_org_factor":.04,"army_attack_factor":-.03},parents=["far_reorganisation"])
# COLDWAR_CUB — IMPERIA CW: expeditionary readiness incurs logistics costs, no workforce reduction.
focus("expeditionary_forces","Expeditionary Forces","defence",2,1,"An overseas commitment needs deployable formations and a permanent support establishment. Sustaining trained contingents increases the military wage bill and requires larger stocks, maintenance reserves and supply shipments.",{"send_volunteer_size":2,"army_org_factor":.06,"army_personnel_cost_multiplier_modifier":.12,"supply_consumption_factor":.05},parents=["far_reorganisation"])
focus("militia_logistics","Militia Logistics","defence",-2,2,"Militia units need common stores, communications and manageable supply requirements. Standardisation improves defensive endurance while preserving the limitations of a locally organised force.",{"army_defence_factor":.03,"supply_consumption_factor":-.05,"army_org_factor":-.02},[tech("CAT_small_arms")],parents=["territorial_defence"])
focus("mission_schools","Mission Schools","defence",2,2,"Officers assigned abroad need language preparation, staff training and experience of long supply lines. An expeditionary school develops specialist capacity at the cost of a more fuel-intensive force.",{"special_forces_cap":.03,"army_fuel_consumption_factor":.05},[doctrine(.50)],parents=["expeditionary_forces"])
focus("air_defence","Soviet Air Defence","defence",0,3,"Soviet equipment can strengthen Cuban air surveillance when both governments agree on assistance. The proposal concerns training and a limited radar installation, not the return of strategic nuclear weapons to the island.",effects=[xp(air=25),offer("air_defence")],parents=[("militia_logistics","mission_schools")],extra_gate="SOV exists; Cuba and the Soviet Union are not at war",icon="CUB_reorganizeair")
focus("coastal_patrols","Coastal Patrols","defence",-2,4,"Protecting approaches and identifying suspicious traffic is a realistic task for Cuba's navy. Training and coastal ship design will improve that service without pretending the country fields a blue-water fleet.",effects=[money(-.25),xp(navy=25),tech("CAT_corvettes")],parents=["air_defence"])
focus("civil_military_pact","Civil Military Pact","defence",2,4,"Commanders need a settled relationship with the civilian administration. A permanent defence settlement improves organisation, while consultation and oversight reduce the executive's freedom to act alone.",{"army_org_factor":.05,"political_power_factor":-.05},parents=["air_defence"])
exclusive("territorial_defence","expeditionary_forces")

group("foreign","Cuba and the Cold War",[42,0],summary="Soviet alignment, independent diplomacy, recipient consent, and the Thälmann island.")
focus("island_diplomacy","An Island's Diplomacy","foreign",0,0,"Cuba's security depends on more than its distance from Florida. Diplomatic relations with neighbours and distant partners can widen its room for manoeuvre without requiring another country to accept Cuban leadership.",effects=[money(-.10),fx("relations",targets=["MEX","JAM"],value=10)],cost=3)
focus("moscow_guarantee","Soviet Assistance","foreign",-4,1,"Closer Soviet cooperation offers equipment, technical expertise and diplomatic support against isolation. Accepting assistance also gives Moscow greater influence over choices Havana would prefer to make independently.",effects=[offer("soviet_assistance")],parents=["island_diplomacy"],extra_gate="SOV exists; not at war with SOV")
focus("havana_voice","Havana's Own Voice","foreign",4,1,"Cuba can remain socialist or sovereign without allowing a single patron to define every relationship. Independent diplomacy improves resilience and influence, while sacrificing some of the commercial advantages of bloc discipline.",{"imp_sanction_resistance":.10,"foreign_influence_modifier":.10,"resource_export_multiplier_modifier":-.05},[money(-.25)],parents=["island_diplomacy"])
focus("cmea_application","Apply to COMECON","foreign",-4,2,"Admission to the Council for Mutual Economic Assistance would place Cuba's economic relationship with the socialist states on a more formal footing. Membership requires an accepted agreement; an application is not a receipt for subsidised imports.",effects=[offer("cmea_admission")],parents=["moscow_guarantee"],extra_gate="SOV exists; admission agreement is reachable before all member-only content",history="Historically Cuba joined in 1972; an earlier admitted application is explicit alternate history")
focus("division_labour","Division of Labour","foreign",-4,3,"Member states can coordinate specialisation and technical standards instead of duplicating every industry. Cuba gains a more secure place for agricultural exports, while accepting less freedom to diversify its own civilian production.",{"agriculture_district_income_tax_modifier":.10,"civilian_factories_productivity":-.05},[tech("CAT_industry")],parents=["cmea_application"],extra_gate="Has actual COLDWAR_CUB_cmea_member spirit; rechecked in the reward guard")
focus("caribbean_neighbours","Caribbean Neighbours","foreign",4,2,"Jamaica, Guyana and the Dominican Republic face their own political constraints. Cuba can pursue normal relations and practical cooperation without treating every neighbouring government as a future revolutionary dependency.",effects=[money(-.15),fx("relations",targets=["JAM","GUY","DOM"],value=15)],parents=[("moscow_guarantee","havana_voice")])
focus("african_mandate","An African Mandate","foreign",4,3,"Any government seeking Cuban assistance must define what it needs and what Cuba can sustain. Training and medical cooperation can accompany military aid; the scope and terms depend on the recipient's request and the resources Havana can commit.",effects=[offer("overseas_mission"),xp(army=15)],parents=["caribbean_neighbours"])
focus("washington_talks","Talks with Washington","foreign",8,3,"Migration, prisoners, property claims and trade stand between Havana and Washington. Negotiations can open a limited diplomatic channel or a broader trade settlement, with the United States deciding its own terms. Guantánamo's status remains a separate question.",effects=[offer("us_normalisation")],parents=["caribbean_neighbours"],extra_gate="USA exists; not at war with USA",icon="multypartycuba")
focus("berlin_havana","Berlin and Havana","foreign",0,4,"The German Democratic Republic offers an industrial partner whose relationship with Cuba need not be reduced to Soviet instructions. A bilateral commission can discuss technical education, public symbolism and the future of Cayo Blanco del Sur.",effects=[offer("ddr_commission")],parents=["island_diplomacy"],extra_gate="DDR exists; Cuba owns and controls State 1252; not at war with DDR",icon="tradeagreementcuba")
focus("thaelmann_name","A Name for Thälmann","foreign",-2,5,"Naming Cayo Blanco del Sur after Ernst Thälmann would honour a communist martyr and the friendship between the two republics. As in the historical gesture of 1972, the island would remain Cuban territory.",effects=[fx("rename_island",name="Ernst Thälmann Island"),fx("relations",targets=["DDR"],value=20)],parents=["berlin_havana"],extra_gate="Date on/after 19 June 1972; DDR exists; Cuba owns and controls State 1252",history="Historical symbolic renaming; no transfer of sovereignty")
focus("caribbean_treaty","A Territorial Agreement","foreign",2,5,"Havana may instead propose a genuine territorial agreement over the island. This would be an alternative to the historical symbolic gesture, requiring an explicit East German decision on compensation and responsibility.",effects=[offer("island_cession")],parents=["berlin_havana"],extra_gate="Date on/after 19 June 1972; DDR exists; Cuba owns and controls State 1252",history="Explicit alternate history: actual cession, never the historical default")
focus("playa_rda","Playa RDA","foreign",-2,6,"A modest cultural and scientific programme can make the renamed island a symbol of cooperation. Both countries must approve any expenditure; a commemorative beach is not a ready-made naval base.",effects=[offer("symbolic_island_cooperation")],parents=["thaelmann_name"],extra_gate="DDR exists; Cuba still owns and controls State 1252")
focus("development_protocol","Development Protocol","foreign",2,6,"A territorial agreement needs a clear protocol for payment, handover and permitted development. Compensation belongs to Cuba, responsibility passes to the DDR, and neither side obtains an automatic industrial complex or a new core claim.",effects=[fx("contract_followup",contract="island_cession")],parents=["caribbean_treaty"],extra_gate="COLDWAR_CUB_island_cession_ratified receipt; State 1252 is owned by DDR; no duplicate payment")
exclusive("moscow_guarantee","havana_voice");exclusive("thaelmann_name","caribbean_treaty")

# Political rows use exact native governing-party slots. Roots enact institutions,
# not permission to use a party that is already governing. No branch resurrects Che.
group("pcc","PCC · Fidel Castro",[6,10],4,"Popular power, family law, community medicine and biotechnology; markets or mobilised construction.")
focus("popular_power","People's Power","pcc",0,0,"Fidel's authority can be given a more durable institutional base through local assemblies and the mass organisations. A stronger party-state coordinates decisions, but it also carries a larger administrative establishment.",{"stability_factor":.04,"political_power_factor":.08,"bureaucracy_cost_multiplier_modifier":.06},icon="CUB_fidelcastro")
focus("party_ministries","Party over Ministry","pcc",-2,1,"Party cadres can ensure that ministries obey a common political direction. Their intervention strengthens the leadership's authority and ideological discipline while reducing the discretion of enterprise managers.",{"political_power_factor":.12,"drift_defence_factor":.08,"civilian_factories_productivity":-.04},parents=["popular_power"])
focus("juceplan_mandate","JUCEPLAN's Mandate","pcc",2,1,"Economic targets need the authority of an institution capable of refusing impossible promises. Giving JUCEPLAN a stronger mandate improves coordination and investment, at the cost of bureaucracy and personal executive freedom.",{"civilian_factories_productivity":.12,"production_speed_buildings_factor":.08,"bureaucracy_cost_multiplier_modifier":.08,"political_power_factor":-.05},parents=["popular_power"])
focus("first_congress","The First Congress","pcc",0,2,"A party congress can settle responsibilities that have depended on Fidel's personal intervention. Cadre rules and a recorded programme will make the state more predictable without converting it into a multiparty republic.",effects=[money(-.20),law("decrease_corruption")],parents=[("party_ministries","juceplan_mandate")],history="Historical 1975 institution; an earlier congress is an alternate timetable")
focus("socialist_constitution","Socialist Constitution","pcc",0,3,"The constitution will define the party's leading role and the place of the assemblies, ministries and social organisations. Constitutional order lends stability while making the administrative costs of the settlement permanent.",{"stability_factor":.06,"bureaucracy_cost_multiplier_modifier":.04},parents=["first_congress"],history="Historical 1976 model; early enactment is alternate history")
# COLDWAR_CUB — IMPERIA CW: Fidel-era family law, primary care and scientific institutions.
focus("family_code","The Family Code","pcc",-4,1,"The Federation of Cuban Women has brought the division of work within the home into the revolutionary debate. Equal responsibilities between spouses must be backed by childcare, maternity protection and opportunities to study and work. Those commitments widen participation while making social provision a continuing public obligation.",{"total_workforce_modifier":.02,"social_cost_multiplier_modifier":.06},[money(-.20)],parents=["popular_power"],history="The Family Code was adopted in February 1975 before the First PCC Congress. Earlier enactment is alternate history. Practical childcare and employment supports accompany the legal principle; numerical effects are balance proposals, not a claim that equality was immediately achieved.")
focus("family_doctor_teams","Family Doctor Teams","pcc",-4,2,"A doctor and a nurse assigned to a neighbourhood can follow families between illness, prevention and recovery. The Lawton experiment will become a programme of community teams linked to the polyclinics. Continuity of care requires training and a larger health budget, while coordinated referrals reduce duplicated work.",{"healthcare_workforce_requirement_modifier":-.06,"health_cost_multiplier_modifier":.05},[money(-.25),law("increase_healthcare_budget")],parents=["family_code"],history="The family doctor-and-nurse pilot began at Lawton on 4 January 1984. The native health-budget tier models sector capacity and spending; no doctors, clinics or clinical outcomes are spawned as separate assets. Earlier introduction is alternate history.")
focus("biological_front","The Biological Front","pcc",4,3,"Interferon research has shown what a small, coordinated scientific team can attempt. A Biological Front linking the CIB and the new CIGB will connect laboratory research with industrial production in Havana. Genetic research needs protected funding and imported equipment, even when ordinary services compete for the same resources.",{"education_cost_multiplier_modifier":.08},[money(-.90),building(854,"industrial_complex"),tech("CAT_genetics",.50)],parents=["first_congress"],cost=7,history="Interferon work and the Biological Front began in 1981; CIB opened in 1982 and CIGB in 1986. The separate meningitis-vaccine centre developed VA-MENGOC-BC. This focus funds research/industrial capacity, not an instant vaccine or mature export sector; an earlier programme is alternate history.")
focus("sdpe_continuity","Continue the SDPE","pcc",-2,4,"Enterprise accounts and material incentives can remain part of socialist planning. Keeping the system rewards efficient managers and producers, but leaves the state a smaller share of the income it generates.",{"civilian_factories_productivity":.10,"agricolture_productivity_modifier":.10,"tax_gain_multiplier_modifier":-.05},parents=["socialist_constitution"])
focus("rectification","Rectify the Revolution","pcc",2,4,"The leadership can reject what it regards as narrow material self-interest and return to mass mobilisation. Public works gain labour and urgency, while managers and researchers lose some autonomy and predictability.",{"total_workforce_modifier":.04,"production_speed_buildings_factor":.08,"civilian_factories_productivity":-.06,"research_speed_factor":-.03},parents=["socialist_constitution"],history="Historical rectification began in 1986; earlier implementation is an alternate choice")
# COLDWAR_CUB — IMPERIA CW: concrete, distinct follow-through for the economic verdict.
focus("peasant_markets","Peasant Markets","pcc",-2,5,"Farmers who fulfil state procurement quotas may sell eligible surplus directly to consumers. Keeping these markets preserves an incentive to produce food that rationed shops struggle to supply. Higher private returns and unequal purchasing power make the policy contentious, while a smaller share of agricultural receipts passes through the state.",{"agricolture_productivity_modifier":.12,"agriculture_district_income_tax_modifier":-.08,"stability_factor":-.02},[money(-.20)],parents=["sdpe_continuity"],history="The bounded free peasant market experiment ran from 1980 until its closure in 1986. Retaining it under continued SDPE is the alternate economic course; earlier introduction is also alternate history. No sugar tonnage or consumer-price series is invented.")
focus("revive_microbrigades","Revive Microbrigades","pcc",2,5,"Workplaces can again release teams for housing, childcare centres and neighbourhood improvements. The microbrigades make social construction a visible collective project, supported by Havana's utilities and access works. Materials, supervision and time away from ordinary production remain real costs of mobilisation.",{"production_speed_buildings_factor":.08,"civilian_factories_productivity":-.03,"social_cost_multiplier_modifier":.05},[money(-.45),building(854,"infrastructure")],parents=["rectification"],cost=7,history="Workplace microbrigades operated in the early 1970s and were revived during rectification in 1986–87. The native asset is explicitly Havana infrastructure for neighbourhood works; no housing building type, fixed apartment count or housing-stock ledger is claimed.")
focus("cuban_socialism","A Cuban Socialism","pcc",0,6,"The revolution's social settlement should be able to survive a change of office-holder. A renewed education commitment and technical training will preserve national skills without pretending that social provision finances itself.",{"education_cost_multiplier_modifier":.05},[money(-.30),law("increase_education_budget"),tech("CAT_electronics")],parents=[("peasant_markets","revive_microbrigades")],cost=7)
exclusive("party_ministries","juceplan_mandate");exclusive("sdpe_continuity","rectification")

group("orthodox","Orthodox Planning Cadres",[14,10],6,"A post-purge Soviet-oriented cadre coalition, not an intact Microfracción in 1970.",status="Counterfactual governing coalition grounded in surviving PSP/planning traditions")
focus("old_party","Old Party Cadres","orthodox",0,0,"The purge of the Microfracción did not erase the older communist administrative tradition. A rehabilitated Soviet-oriented coalition would promise disciplined government and expertise, while accepting greater exposure to Moscow's influence.",{"political_power_factor":.08,"research_speed_factor":.03,"foreign_influence_defense_modifier":-.08})
focus("five_year_balances","Five-Year Balances","orthodox",-2,1,"A national plan can protect farms and factories from abrupt changes of priority. Stable allocations improve output but leave less room to redirect investment when local conditions change.",{"agricolture_productivity_modifier":.15,"civilian_factories_productivity":.08,"production_speed_buildings_factor":-.05},parents=["old_party"])
focus("enterprise_accounts","Enterprise Accounts","orthodox",2,1,"Production targets should be backed by accounts that expose waste and reward delivery. Enterprise responsibility improves industrial efficiency while diverting resources from agricultural mobilisation and reducing immediate revenue extraction.",{"civilian_factories_productivity":.12,"production_factory_efficiency_gain_factor":.10,"agricolture_productivity_modifier":-.03,"tax_gain_multiplier_modifier":-.03},parents=["old_party"])
focus("cadre_schools","Cadre Schools","orthodox",-2,2,"The plan needs administrators able to read technical reports and manage institutions. Specialised schools strengthen research capacity, while adding to the education establishment that the state must maintain.",{"research_speed_factor":.04,"education_cost_multiplier_modifier":.06},parents=["five_year_balances"])
focus("manager_responsibility","Managerial Duty","orthodox",2,2,"Managers should be accountable for results rather than merely for optimistic reports. The resulting flexibility improves production and technical work, but unsettles cadres who relied on political protection.",{"civilian_factories_productivity":.06,"research_speed_factor":.02,"stability_factor":-.02},parents=["enterprise_accounts"])
focus("soviet_standards","Common Standards","orthodox",0,3,"Common engineering standards will make imported machinery easier to maintain. Technical education offers a durable national gain while the current coalition remains responsible for the political terms of cooperation.",effects=[money(-.35),tech("CAT_industry",.25,2)],parents=[("cadre_schools","manager_responsibility")])
focus("planned_republic","A Planned Republic","orthodox",0,4,"A disciplined planning republic can deliver a larger and more dependable agricultural surplus. Achieving it requires a permanent administrative network, not an assumption that every local producer will obey without supervision.",{"agricolture_productivity_modifier":.05,"tax_gain_multiplier_modifier":.05,"bureaucracy_cost_multiplier_modifier":.04},parents=["soviet_standards"],cost=7)
exclusive("five_year_balances","enterprise_accounts")

group("guevarist","Guevarist Mobilisation",[22,10],19,"Moral incentives or worker participation; a living political current, not Che's return.")
focus("unfinished_revolution","The New Man","guevarist",0,0,"Che's death left an ideal that still commands loyalty among militants and young volunteers. A government built around revolutionary commitment can mobilise labour, while its suspicion of technocratic autonomy constrains research.",{"total_workforce_modifier":.03,"drift_defence_factor":.10,"research_speed_factor":-.04},icon="mobilizeyoungpeoplecub")
focus("moral_incentives","Moral Incentives","guevarist",-2,1,"Public recognition and collective duty will take precedence over individual material rewards. Brigades can build and harvest quickly, but industrial managers cannot rely on the same incentives as a wage-led enterprise.",{"production_speed_buildings_factor":.14,"agricolture_productivity_modifier":.08,"civilian_factories_productivity":-.08},parents=["unfinished_revolution"])
focus("workers_assemblies","Workers' Assemblies","guevarist",2,1,"A more participatory socialism would place workplace debates inside the production process. Worker initiative and available skills can improve output, while consultation reduces the government's ability to issue rapid commands.",{"civilian_factories_productivity":.10,"total_workforce_modifier":.02,"political_power_factor":-.08},parents=["unfinished_revolution"],history="Plausible alternate institutional form; no claim of an existing ownership simulator")
focus("young_brigades","The Young Brigades","guevarist",-2,2,"Young volunteers can be assigned a defined infrastructure project instead of another limitless campaign. The work remains a national asset after political fashions change, and the construction budget must still be paid.",effects=[money(-.50),building(1121,"infrastructure")],parents=["moral_incentives"],cost=7)
focus("factory_councils","Factory Councils","guevarist",2,2,"Councils can take responsibility for maintenance and training at the factory floor. Local initiative improves civilian production, while less uniform working methods limit the gains available from a single national production standard.",{"civilian_factories_productivity":.08,"education_cost_multiplier_modifier":.06,"production_factory_max_efficiency_factor":-.04},parents=["workers_assemblies"])
focus("solidarity_profit","Solidarity First","guevarist",0,3,"International solidarity is a commitment of people and resources rather than an export commodity. The government can sustain an additional volunteer formation, while accepting higher recurring military personnel expenditure.",{"send_volunteer_size":1,"army_personnel_cost_multiplier_modifier":.05},[xp(army=25)],parents=[("young_brigades","factory_councils")],cost=7)
exclusive("moral_incentives","workers_assemblies")

group("far","FAR · National Administration",[30,10],22,"Raúl's professional military current, administrative engineering or a combat-first force.",status="Counterfactual FAR-led government; Raúl remains defence minister at the historical 1970 start")
focus("professional_revolution","Professional Rule","far",0,0,"The FAR's professional officers can promise a disciplined succession and a state that carries out its decisions. Military management improves organisation and administrative efficiency while narrowing civilian political autonomy.",{"army_org_factor":.06,"bureaucracy_cost_multiplier_modifier":-.04,"political_power_factor":-.08},icon="CUB_raulcaro")
focus("barracks_workshops","Barracks and Works","far",-2,1,"Military engineering and procurement organisations can be used to deliver civilian projects. Their discipline accelerates construction and production, but a larger permanent military establishment draws labour away from other work.",{"production_speed_buildings_factor":.12,"civilian_factories_productivity":.06,"total_workforce_modifier":-.02},parents=["professional_revolution"])
focus("soldiers_not_managers","Soldiers, Not Firms","far",2,1,"The armed forces can refuse a permanent role in commercial management and concentrate on readiness. Better organisation and faster training then come at the expense of the engineering capacity that civilian projects might have borrowed.",{"army_org_factor":.10,"training_time_army_factor":-.08,"production_speed_buildings_factor":-.04},parents=["professional_revolution"])
focus("military_engineering","Military Engineers","far",-2,2,"An eastern infrastructure programme gives military engineers a concrete civilian assignment. The investment improves national connections without turning the armed forces into an unlimited source of free construction.",effects=[money(-.55),building(855,"infrastructure"),xp(army=15)],parents=["barracks_workshops"],cost=7)
focus("command_college","A Command College","far",2,2,"A professional command college can turn operational experience into a common doctrine. Its instructors and facilities require funding, while the knowledge earned by the officer corps remains a national asset.",effects=[money(-.30),xp(army=25),doctrine(.50)],parents=["soldiers_not_managers"])
focus("accountable_officers","Accountable Officers","far",0,3,"Procurement and promotion need standards that bind commanders as well as civilians. Audits reduce corruption and improve confidence, while a professional establishment carries a higher personnel bill than informal revolutionary service.",{"stability_factor":.03,"army_personnel_cost_multiplier_modifier":.05},[law("decrease_corruption")],parents=[("military_engineering","command_college")])
focus("orderly_succession","Orderly Succession","far",0,4,"The government will define how authority passes between offices instead of leaving succession to personal allegiance. The settlement improves continuity, while a less personalised revolutionary identity offers weaker protection against ideological drift.",{"political_power_factor":.08,"stability_factor":.06,"army_org_factor":.03,"drift_defence_factor":-.05},parents=["accountable_officers"],cost=7)
exclusive("barracks_workshops","soldiers_not_managers")

group("autentico","Auténtico · Social Republic",[38,10],3,"Labour guarantees or a negotiated investment settlement under the republican tradition.",status="Alternate constitutional transition; no legal domestic Auténtico party apparatus in January 1970")
focus("authentic_republic","The Social Republic","autentico",0,0,"The Auténtico tradition can reclaim the republic without abandoning social insurance and national sovereignty. A negotiated return broadens confidence and inward migration, but rebuilding civilian institutions requires an administrative settlement.",{"migration_rate_value_factor":.03,"stability_factor":.04,"bureaucracy_cost_multiplier_modifier":.05})
focus("labour_guarantee","Labour's Guarantee","autentico",-2,1,"Trade unions and workers need enforceable guarantees that political change will not erase the revolution's social gains. Those guarantees widen participation and confidence, while raising the cost of the welfare settlement.",{"total_workforce_modifier":.05,"stability_factor":.06,"social_cost_multiplier_modifier":.10},parents=["authentic_republic"])
focus("investment_rights","Investment with Rights","autentico",2,1,"Investment can be welcomed without restoring an unrestricted pre-revolutionary property order. Production and construction benefit, while negotiated concessions reduce the revenue immediately captured by the state.",{"civilian_factories_productivity":.12,"production_speed_buildings_factor":.08,"tax_gain_multiplier_modifier":-.06},parents=["authentic_republic"])
focus("social_insurance","Social Insurance","autentico",-2,2,"A republican government will fund a health service that survives a change of party. Expanding public healthcare is a lasting institutional commitment with a continuing fiscal cost.",{"health_cost_multiplier_modifier":.05},[money(-.30),law("increase_healthcare_budget")],parents=["labour_guarantee"])
focus("mixed_economy","A Mixed Economy","autentico",2,2,"Private enterprise, cooperatives and a public sector can coexist under a common administrative framework. Integrating displaced families into ordinary work is a practical test of that promise, and requires more than a declaration of reconciliation.",{"imp_refugee_integration_rate":.20,"civilian_factories_productivity":.05,"bureaucracy_cost_multiplier_modifier":.06},[money(-.25)],parents=["investment_rights"])
focus("authentic_settlement","An Authentic Pact","autentico",0,3,"The settlement should bind labour leaders, public officials and enterprise managers to transparent rules. Reducing corruption and sustaining education give the restored republic substance beyond an anti-Castro coalition.",effects=[money(-.30),law("decrease_corruption"),law("increase_education_budget")],parents=[("social_insurance","mixed_economy")],cost=7)
exclusive("labour_guarantee","investment_rights")

group("ortodoxo","Ortodoxo · Sovereign Republic",[6,18],18,"Chibás's anti-corruption and social-national tradition, separate from the Auténticos.",status="Alternate constitutional coalition drawing on surviving Ortodoxo traditions")
focus("shame_money","Integrity over Money","ortodoxo",0,0,"The moral authority of Chibás rests on honest government rather than another patronage machine. An Ortodoxo cabinet will begin by confronting corruption, accepting the cost of an administration capable of investigating its own supporters.",{"bureaucracy_cost_multiplier_modifier":.03},[law("decrease_corruption")])
focus("independent_republic","Sovereign Republic","ortodoxo",-2,1,"Neither Soviet tutelage nor a return to American predominance can define the new republic. A sovereign course strengthens resistance to outside pressure, while limiting some opportunities for foreign commerce.",{"foreign_influence_defense_modifier":.20,"imp_sanction_resistance":.10,"resource_export_multiplier_modifier":-.08},parents=["shame_money"])
focus("social_republic","Social Citizenship","ortodoxo",2,1,"National independence must have a social purpose. Education and access to work can widen the republic's domestic foundation, while a larger welfare settlement makes demands on the weekly budget.",{"research_speed_factor":.06,"total_workforce_modifier":.03,"social_cost_multiplier_modifier":.12},parents=["shame_money"])
focus("public_accounts","Public Accounts","ortodoxo",-2,2,"An honest revenue system needs published accounts and officials who can resist discretionary favours. Tax collection and administrative efficiency improve, while stronger oversight constrains executive political freedom.",{"tax_gain_multiplier_modifier":.08,"bureaucracy_cost_multiplier_modifier":-.05,"political_power_factor":-.05},parents=["independent_republic"])
focus("land_labour","Land and Labour","ortodoxo",2,2,"Agrarian reform can be defended without allowing every farm decision to be made in Havana. Better incentives raise output and available work, while the treasury relinquishes part of its agricultural district receipts.",{"agricolture_productivity_modifier":.14,"total_workforce_modifier":.02,"agriculture_district_income_tax_modifier":-.08},parents=["social_republic"])
focus("promise_1940","The Promise of 1940","ortodoxo",0,3,"The constitution's social and national promises need courts, public scrutiny and a government willing to be bound by them. Stability and research benefit from predictable institutions, while executive bargaining becomes more demanding.",{"stability_factor":.06,"research_speed_factor":.04,"political_power_factor":-.04},parents=[("public_accounts","land_labour")],cost=7)
exclusive("independent_republic","social_republic")

group("christian","Christian Democratic Movement",[14,18],1,"Subsidiarity or a national social-market compact; church mediation without a theocracy.",status="Alternate civic transition; secular Christian-democratic government, not a religious-state fantasy")
focus("civic_reconciliation","Civic Reconciliation","christian",0,0,"Christian democrats can offer an institutional bridge between religious citizens, moderate exiles and a population dependent on public services. Reconciliation strengthens confidence and inward migration, while rebuilding municipal administration has a cost.",{"migration_rate_value_factor":.03,"stability_factor":.03,"bureaucracy_cost_multiplier_modifier":.05})
focus("subsidiarity","Subsidiarity","christian",-2,1,"Municipalities and voluntary institutions should carry responsibilities they can fulfil locally. A smaller central bureaucracy and more responsive enterprises come at the price of a narrower national tax base.",{"bureaucracy_cost_multiplier_modifier":-.12,"civilian_factories_productivity":.08,"tax_gain_multiplier_modifier":-.05},parents=["civic_reconciliation"])
focus("social_market","Social-Market Pact","christian",2,1,"Employers, workers and the government can bargain over a shared social-market settlement. Participation and reliable revenue improve, while nationally guaranteed benefits remain an obligation of the weekly budget.",{"total_workforce_modifier":.03,"tax_gain_multiplier_modifier":.08,"social_cost_multiplier_modifier":.10},parents=["civic_reconciliation"])
focus("parish_municipality","Parish and Town","christian",-2,2,"Local schools and voluntary associations can help displaced families enter ordinary civic life. Their contribution reduces public provision costs, while concentrating resources on basic services rather than specialist research.",{"education_cost_multiplier_modifier":-.08,"imp_refugee_integration_rate":.15,"research_speed_factor":-.01},parents=["subsidiarity"])
focus("family_wages","Family and Wages","christian",2,2,"A family policy needs healthcare and a dependable social wage rather than slogans about morality. Public healthcare receives additional funding, with population and fiscal effects that develop over time.",{"monthly_population":.03,"health_cost_multiplier_modifier":.05},[law("increase_healthcare_budget")],parents=["social_market"])
focus("pluralist_covenant","Pluralist Covenant","christian",0,3,"A durable covenant must protect believers and non-believers and bind the government to constitutional rights. Broader legitimacy strengthens the country against outside pressure, while negotiation limits the executive's personal freedom.",{"stability_factor":.05,"foreign_influence_defense_modifier":.10,"political_power_factor":-.05},parents=[("parish_municipality","family_wages")],cost=7)
exclusive("subsidiarity","social_market")

group("liberal","Constitutional Liberal Republic",[22,18],2,"Claims bonds or property restitution, courts and a free public sphere.",status="Alternate constitutional transition; compensation requires negotiated claims, not automatic US consent")
focus("courts_factions","Courts before Factions","liberal",0,0,"The constitutionalists' first task is to bind the victors to rules they cannot change for private advantage. Independent courts improve confidence in research and administration, while limiting executive political discretion.",{"research_speed_factor":.03,"political_power_factor":-.06},[law("decrease_corruption")])
focus("compensation_bonds","Claims Bonds","liberal",-2,1,"Compensation bonds can acknowledge lawful claims without evicting every current occupier. The settlement protects stability and resilience, while adding a real public debt obligation; it is not a cash windfall for the government.",{"stability_factor":.07,"imp_sanction_resistance":.08},[fx("debt",amount=.50)],parents=["courts_factions"])
focus("restitution","Guarded Restitution","liberal",2,1,"Restitution under judicial safeguards can attract exile capital more quickly than a long bond settlement. It also reopens disputes over homes, farms and employment, with an immediate social cost.",{"civilian_factories_productivity":.15,"production_speed_buildings_factor":.08,"stability_factor":-.05,"total_workforce_modifier":-.01},parents=["courts_factions"])
focus("judicial_guarantees","Judicial Guarantees","liberal",-2,2,"Enforceable rights will make it easier to integrate displaced people and replace discretionary administrative decisions. Judicial independence improves that process, while restricting the government's political leverage over individual cases.",{"imp_refugee_integration_rate":.20,"bureaucracy_cost_multiplier_modifier":-.08,"political_power_factor":-.04},parents=["compensation_bonds"])
focus("commercial_courts","Commercial Courts","liberal",2,2,"Commercial courts can make investment contracts credible without surrendering the right to regulate them. Construction and enterprise output benefit, while tax concessions form part of the negotiated settlement.",{"production_speed_buildings_factor":.10,"civilian_factories_productivity":.06,"tax_gain_multiplier_modifier":-.05},parents=["restitution"])
focus("open_press","An Open Press","liberal",0,3,"An open press can expose official failure and widen technical debate. Research benefits from the circulation of ideas, while a less controlled public sphere is also more accessible to foreign influence.",{"research_speed_factor":.07,"foreign_influence_defense_modifier":-.10},parents=[("judicial_guarantees","commercial_courts")])
focus("constitutional_order","Constitutional Order","liberal",0,4,"A competitive republic needs a revenue system and an administration that can serve an opposition government as well as the current cabinet. Better collection and expertise require maintaining that public establishment.",{"tax_gain_multiplier_modifier":.08,"research_speed_factor":.03,"bureaucracy_cost_multiplier_modifier":.04},parents=["open_press"],cost=7)
exclusive("compensation_bonds","restitution")

group("rece","RECE · Exile Directorate",[30,18],0,"A hard anti-communist transition with a choice between restoration and state-led rebuilding.",status="Counterfactual exile-backed regime; requires an actual negotiated or coercive transition")
focus("exile_directorate","Exile Directorate","rece",0,0,"An exile directorate would bring organised outside contacts and a command structure to a fractured transition. Its authority improves military coordination and diplomacy, while lacking the domestic legitimacy of a settled constitutional order.",{"army_org_factor":.05,"foreign_influence_modifier":.10,"stability_factor":-.05},icon="anticastroidea")
focus("restoration_first","Restoration First","rece",-2,1,"Returning capital and commercial networks can rebuild civilian production quickly. An uncompromising restoration also deepens property conflict and makes the new order more vulnerable to the patrons on which it relies.",{"civilian_factories_productivity":.18,"production_speed_buildings_factor":.10,"foreign_influence_defense_modifier":-.12,"stability_factor":-.04},parents=["exile_directorate"])
focus("development_first","Development First","rece",2,1,"The directorate can postpone full restitution and make reconstruction its first claim to authority. Publicly directed investment improves construction and resilience, while maintaining a costly administrative machine.",{"production_speed_buildings_factor":.18,"imp_sanction_resistance":.08,"bureaucracy_cost_multiplier_modifier":.08,"civilian_factories_productivity":-.02},parents=["exile_directorate"])
focus("national_settlement","National Settlement","rece",0,2,"The transition cannot be governed indefinitely by rival exile committees. A settlement against patronage and private revenge improves confidence, while requiring the directorate to surrender some of its discretion.",{"stability_factor":.05,"political_power_factor":-.04},[money(-.30),law("decrease_corruption")],parents=[("restoration_first","development_first")])
focus("provisional_charter","Provisional Charter","rece",0,3,"A provisional charter must say who will govern after the emergency. A civilian timetable and an extended directorate are different settlements, to be resolved through the existing party system rather than by replaying reconstruction rewards.",effects=[fx("transition_charter")],parents=["national_settlement"],cost=7)
exclusive("restoration_first","development_first")

group("alpha","Alpha 66 · National Liberation",[38,18],20,"Civic demobilisation or an armed nationalist settlement; distinct from RECE and Batista.",status="Counterfactual governing role for a real militant exile movement")
focus("cuban_liberation","Cuban-Led Liberation","alpha",0,0,"Alpha 66's armed exile networks would need to form a governing coalition after Castro's fall. A nationalist cabinet could defend sovereignty while placing stricter conditions on outside commerce, reducing resource export earnings.",{"army_core_defence_factor":.08,"foreign_influence_defense_modifier":.15,"resource_export_multiplier_modifier":-.06},icon="risemilitarismcub")
focus("civic_resistance","A Civic Resistance","alpha",-2,1,"The movement can convert resistance networks into civilian organisations and seek the return of families abroad. Research and inward migration benefit, while the armed establishment loses some of its cohesion and priority.",{"research_speed_factor":.05,"migration_rate_value_factor":.05,"army_org_factor":-.03},parents=["cuban_liberation"])
focus("veterans_directorate","Veterans' Directorate","alpha",2,1,"Veterans can instead retain a central role in the state and build a professional nationalist force. Readiness improves, while military priorities constrain civilian enterprise and political bargaining.",{"army_org_factor":.12,"training_time_army_factor":-.08,"civilian_factories_productivity":-.06,"political_power_factor":-.05},parents=["cuban_liberation"])
focus("veterans_civil_life","Veterans into Work","alpha",-2,2,"Demobilisation should provide ordinary work rather than abandon veterans to factional patrons. The economy gains labour and the army budget contracts, at the cost of a smaller specialist military establishment.",{"total_workforce_modifier":.04,"army_personnel_cost_multiplier_modifier":-.08,"special_forces_cap":-.02},parents=["civic_resistance"])
focus("armed_sovereignty","Armed Sovereignty","alpha",2,2,"A fortified sovereign republic can resist pressure from old patrons as well as new enemies. Its defensive strength and resilience come with a larger supervisory state and less room for independent research.",{"army_core_defence_factor":.10,"imp_sanction_resistance":.12,"research_speed_factor":-.04,"bureaucracy_cost_multiplier_modifier":.04},parents=["veterans_directorate"],cost=7)
exclusive("civic_resistance","veterans_directorate")

group("ospaaal","OSPAAAL · Tricontinental Solidarity",[46,10],5,"Diplomatic solidarity or a larger overseas cadre network.",status="Counterfactual governing alignment represented by a registered current; OSPAAAL was an international solidarity organization, not a Cuban political party")
focus("tricontinental_secretariat","Tricontinental Secretariat","ospaaal",0,0,"An OSPAAAL-led governing alignment would place the Tricontinental network at the centre of Cuban diplomacy. Its established channels increase international influence, while coordinating them adds to the administrative burden.",{"foreign_influence_modifier":.06,"bureaucracy_cost_multiplier_modifier":.03},icon="tradeagreementcuba")
focus("diplomatic_solidarity","Diplomatic Solidarity","ospaaal",-2,1,"Political solidarity can be carried through conferences, public campaigns and non-military exchanges. Cuba gains influence among partners without diverting a large share of trained labour into permanent overseas missions.",{"foreign_influence_modifier":.10,"foreign_influence_defense_modifier":.05,"total_workforce_modifier":-.005},parents=["tricontinental_secretariat"],icon="tradeagreementcuba")
focus("foreign_cadres","Foreign Cadres","ospaaal",2,1,"Havana can instead expand the cadres assigned to liberation movements and allied institutions. The wider network strengthens Cuban influence, but takes trained staff from domestic services and makes independent diplomacy harder.",{"foreign_influence_modifier":.18,"total_workforce_modifier":-.025,"bureaucracy_cost_multiplier_modifier":.08,"foreign_influence_defense_modifier":-.05},parents=["tricontinental_secretariat"],icon="risemilitarismcub")
exclusive("diplomatic_solidarity","foreign_cadres")

group("minint","MININT · Interior Administration",[46,18],7,"Professional intelligence or intensive mass surveillance.",status="Counterfactual security-led government represented by a registered state institution, not a separate historical party")
focus("interior_ministry","The Interior Ministry","minint",0,0,"A MININT-led administration would make internal security the first responsibility of the state. Counterintelligence and executive coordination improve, while the larger security apparatus raises bureaucratic costs and narrows political discretion.",{"intelligence_agency_defense":.15,"bureaucracy_cost_multiplier_modifier":.06,"political_power_factor":-.03},icon="CUB_far_cub")
focus("professional_intelligence","Professional Intelligence","minint",-2,1,"A smaller professional service can concentrate on foreign penetration, critical infrastructure and accountable investigations. Better analysis aids research and defensive security, though specialised personnel and oversight remain costly.",{"intelligence_agency_defense":.10,"research_speed_factor":.03,"bureaucracy_cost_multiplier_modifier":.04,"total_workforce_modifier":-.005},parents=["interior_ministry"],icon="CUB_reorganizeair")
focus("mass_surveillance","Mass Surveillance","minint",2,1,"The ministry can instead expand local surveillance and political reporting through mass organisations. This increases the state's capacity to watch and control, while skilled workers leave productive services and public debate becomes more restricted.",{"intelligence_agency_defense":.20,"political_power_factor":-.08,"research_speed_factor":-.05,"total_workforce_modifier":-.02,"foreign_influence_defense_modifier":-.08},parents=["interior_ministry"],icon="risemilitarismcub")
exclusive("professional_intelligence","mass_surveillance")

group("juceplan","JUCEPLAN · Central Planning Board",[54,10],13,"Balanced national plans or enterprise incentives and delegated initiative.",status="Counterfactual technocratic government represented by a registered planning institution, not a separate historical party")
focus("plan_balances","National Plan Balances","juceplan",0,0,"A JUCEPLAN-led government would begin by reconciling production targets with transport, labour and imported inputs. Better coordination supports civilian output, while the planning apparatus adds a permanent administrative cost.",{"civilian_factories_productivity":.05,"agricolture_productivity_modifier":.04,"bureaucracy_cost_multiplier_modifier":.05},icon="cuban_economy_peso_new")
focus("balanced_targets","Balanced Targets","juceplan",-2,1,"Investment plans can protect maintenance, food production and consumer goods alongside export targets. Agricultural and civilian output improve together, while slower capital concentration limits construction speed.",{"agricolture_productivity_modifier":.10,"civilian_factories_productivity":.06,"production_speed_buildings_factor":-.04},parents=["plan_balances"],icon="sugartobaccocuba")
focus("enterprise_incentives","Enterprise Incentives","juceplan",2,1,"Managers and work collectives can receive clearer production targets and retain a larger role in local decisions. Factory efficiency and civilian output rise, while agricultural planning and central tax receipts lose some priority.",{"civilian_factories_productivity":.10,"production_factory_efficiency_gain_factor":.05,"agricolture_productivity_modifier":-.04,"tax_gain_multiplier_modifier":-.04},parents=["plan_balances"],icon="cuban_economy_peso_new")
exclusive("balanced_targets","enterprise_incentives")

